from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

import pandas as pd


DEFAULT_PROPERTIES = [
    "volume_resistivity_ohm_cm",
    "gas_diffusion_cm2_s",
    "dielectric_constant",
    "tensile_break_GPa",
    "refractive_index",
    "surface_tension_mN_m",
    "CTE_ppm_K",
    "water_absorption_pct",
]


def read_canonical_panel(output_dir: Path, stem: str) -> pd.DataFrame:
    """Read the panel generated by V11's canonical formula only."""
    canonical = output_dir / f"{stem}_canonical_distance_sigma.csv"
    if canonical.exists():
        return pd.read_csv(canonical)
    candidates = sorted(output_dir.glob(f"{stem}_canonical_distance_sigma_*.csv"))
    if candidates:
        return pd.read_csv(candidates[-1])
    raise FileNotFoundError(
        f"No canonical panel file found for {stem!r} in {output_dir}"
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outputs-dir", type=Path, default=Path("outputs"))
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=Path("outputs/09_score_error_validation_selected_single_properties"),
    )
    parser.add_argument("--properties", nargs="+", default=DEFAULT_PROPERTIES)
    parser.add_argument("--dpi", type=int, default=450)
    args = parser.parse_args()

    script = Path(__file__).resolve().parent / "13_plot_score_error_validation_tg.py"
    args.output_dir.mkdir(parents=True, exist_ok=True)

    rows = []
    for prop in args.properties:
        input_path = args.outputs_dir / "02_oof_reliability_scores" / f"{prop}_oof_reliability.csv"
        if not input_path.exists():
            rows.append({"property": prop, "status": "missing_input"})
            print(f"SKIP {prop}: missing {input_path}", flush=True)
            continue
        prop_out = args.output_dir / prop
        prop_out.mkdir(parents=True, exist_ok=True)
        cmd = [
            sys.executable,
            str(script),
            "--input",
            str(input_path),
            "--output-dir",
            str(prop_out),
            "--property-name",
            prop,
            "--title-property",
            prop.replace("_", " "),
            "--dpi",
            str(args.dpi),
        ]
        print("RUN:", " ".join(cmd), flush=True)
        completed = subprocess.run(cmd, check=False, capture_output=True, text=True)
        if completed.stdout:
            print(completed.stdout.strip(), flush=True)
        if completed.stderr:
            print(completed.stderr.strip(), flush=True)
        status = "success" if completed.returncode == 0 else "error"

        diag = {
            "property": prop,
            "status": status,
            "output_dir": str(prop_out),
        }
        try:
            panel_a = read_canonical_panel(prop_out, "panel_a_score_decile_error")
            panel_b = read_canonical_panel(prop_out, "panel_b_selective_retention")
            source = pd.read_csv(input_path)
            diag.update(
                {
                    "n_oof": int(panel_a["n"].sum()),
                    "d1_median_error": float(panel_a.iloc[0]["median_normalized_error"]),
                    "d10_median_error": float(panel_a.iloc[-1]["median_normalized_error"]),
                    "top10_mae": float(panel_b.iloc[0]["confidence_ranked_mae"]),
                    "full_mae": float(panel_b.iloc[-1]["confidence_ranked_mae"]),
                    "oof_r2_proxy": float(1.0 - float(source["property_nrmse"].iloc[0]) ** 2),
                    "property_nrmse": float(source["property_nrmse"].iloc[0]),
                }
            )
        except Exception as exc:
            diag["summary_error"] = str(exc)
        rows.append(diag)

    summary = pd.DataFrame(rows)
    summary.to_csv(args.output_dir / "selected_single_property_validation_summary.csv", index=False)
    print({"summary": str(args.output_dir / "selected_single_property_validation_summary.csv")})
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
